        {
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_de_Alencar", Text = "É uma história curiosa a que lhe vou contar, minha prima. Mas é uma história e não um romance.", Author = "José de Alencar" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_de_Alencar", Text = "Cada região da terra tem uma alma sua, raio criador que lhe imprime o cunho da originalidade.", Author = "José de Alencar" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_de_Alencar", Text = "A natureza infiltra em todos os seres que ela gera e nutre aquela seiva própria: e forma assim uma família na grande sociedade universal.", Author = "José de Alencar" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_de_Alencar", Text = "É que o prazer e o sofrimento não passam de um contraste; em lata perpétua e continua, eles se acrisolam um no outro, e se deparam: não há homem verdadeiramente feliz senão aquele que já conheceu a desgraça.", Author = "José de Alencar" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_de_Alencar", Text = "Pouco e pouco o dia foi rompendo; o arrebol da manhã desenhou-se no horizonte, tingindo as nuvens com todas as cores do prisma.", Author = "José de Alencar" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_de_Alencar", Text = "O primeiro raio do sol, desprendendo-se daqueles vapores tênues e diáfanos, deslizou pelo azul do céu, e foi brincar no cabeço dos montes.", Author = "José de Alencar" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_de_Alencar", Text = "Para eles esse sol era a imagem de sua vida; o ocaso era a sua hora derradeira: e as sombras da eternidade se estendiam já como as sombras da noite.", Author = "José de Alencar" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_de_Alencar", Text = "É ao mesmo tempo o nada com o seu vácuo profundo, imenso, infinito; e o caos com a sua confusão, as suas trevas, as suas formas incriadas; a alma sente que falta-lhe a vida ou a luz em torno.", Author = "José de Alencar" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_de_Alencar", Text = "As altas montanhas, as nuvens, as catadupas, os grandes rios, as árvores seculares, serviam de trono, de dossel, de manto e cetro a esse monarca das selvas cercado de toda a majestade e de todo o esplendor da natureza.", Author = "José de Alencar" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_de_Alencar", Text = "O sol, dissipando as trevas da noite, assomou no oriente; seu aspecto majestoso iluminou o deserto; as ondas de sua luz brilhante derramaram-se em cascatas sobre um lago imenso, sem horizontes.", Author = "José de Alencar" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_de_Alencar", Text = "Iracema, a virgem dos lábios de mel, que tinha os cabelos mais negros que a asa da graúna e mais longos que seu talhe de palmeira.", Author = "José de Alencar" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_de_Alencar", Text = "O favo de jati não era doce como seu sorriso; nem a bunilha recendia no bosque como seu hálito perfumado.", Author = "José de Alencar" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_de_Alencar", Text = "Verdes mares bravios de minha terra natal, onde canta a jandaia nas frondes da carnaúba; verdes mares, que brilhais como líquida esmeralda aos raios do sol nascente, perlongando as alvas praias ensombradas de coqueiros.", Author = "José de Alencar" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_de_Alencar", Text = "Já estava eu meio descrido das coisas, e mais dos homens;e por isso buscava na literatura diversão à tristeza que me infundia o estado da pátria entorpecida pela indiferença.", Author = "José de Alencar" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/José_de_Alencar", Text = "É na idade da ambição que se prova a têmpera dos homens.", Author = "José de Alencar" },
